<script setup lang="ts">
import { computed, inject, ref } from 'vue';
import { path } from '@tauri-apps/api';
import { EXECUTABLE_OS, GameActionsKey } from '@/constants/constants';
import type { GameActionsProvider, Game, GameExecutable } from '@/types/types';
import MinutePicker from '@/components/MinutePicker.vue';

const props = defineProps<{ game: Game }>();
const emit = defineEmits<{ play: [{ game: Game; executable: GameExecutable }]; stop: [{ game: Game; executable: GameExecutable }]; install_and_play: [{ game: Game; executable: GameExecutable }]; pause_timer: [{ game: Game; executable: GameExecutable }]; resume_timer: [{ game: Game; executable: GameExecutable }]; cancel_timer: [{ game: Game; executable: GameExecutable }] }>();
const gameActions = inject<GameActionsProvider>(GameActionsKey);
const timerMinutes = ref<Record<string, number | null>>({});
const filteredExecutables = computed(() => props.game.executables.filter((executable) => executable.os !== EXECUTABLE_OS.LINUX && executable.os !== EXECUTABLE_OS.DARWIN && !isInvalidPath(executable.name)));
function splitExecutableName(executable: GameExecutable) { const sections = executable.name.split(/\\|\//); const last = sections[sections.length - 1]; return [...sections.slice(0, -1), last?.split('.').slice(0, -1).join('.') || last || '']; }
function getExecutablePath(executable: GameExecutable) { return executable.name.split(/\\|\//).slice(0, -1).join(path.sep()); }
function getFilename(executable: GameExecutable) { const sections = executable.name.split(/\\|\//); return sections[sections.length - 1]; }
function formatRemaining(seconds = 0) { const safeSeconds = Math.max(0, Math.ceil(seconds)); const hours = Math.floor(safeSeconds / 3600); const minutes = Math.floor((safeSeconds % 3600) / 60); const remainder = safeSeconds % 60; return hours > 0 ? `${hours}:${String(minutes).padStart(2, '0')}:${String(remainder).padStart(2, '0')}` : `${minutes}:${String(remainder).padStart(2, '0')}`; }
function timerProgress(executable: GameExecutable) { return !executable.timer_minutes || executable.timer_remaining_seconds === undefined ? 0 : Math.min(100, Math.max(0, executable.timer_remaining_seconds / (executable.timer_minutes * 60) * 100)); }
function handleTimerToggle(executable: GameExecutable) { if (executable.timer_paused) { emit('resume_timer', { game: props.game, executable }); } else { emit('pause_timer', { game: props.game, executable }); } }
function handleCancelTimer(executable: GameExecutable) { timerMinutes.value[executable.name] = null; emit('cancel_timer', { game: props.game, executable }); }
function isInvalidPath(value: string) { return ['>', '<', ':', '"', '|', '?', '*'].some((character) => value.includes(character)); }
function handleLaunch(executable: GameExecutable) { const resolved = { path: getExecutablePath(executable), segments: splitExecutableName(executable).length, filename: getFilename(executable), ...executable, timer_minutes: timerMinutes.value[executable.name] ?? null }; if (executable.is_running) { emit('stop', { game: props.game, executable: resolved }); } else if (!gameActions?.isGameExecutableInstalled(executable)) { emit('install_and_play', { game: props.game, executable: resolved }); } else { emit('play', { game: props.game, executable: resolved }); } }
</script>

<template>
  <section><h3 class="text-xs font-semibold uppercase tracking-[0.06em] text-app-text-muted">Executables</h3><div class="mt-3 space-y-2 rounded-[18px] bg-app-panel p-3 shadow-inset"><p v-if="filteredExecutables.length === 0" class="px-2 py-3 text-sm text-app-text-muted">No supported Windows executables are available.</p><article v-for="executable in filteredExecutables" :key="executable.name" class="rounded-[14px] bg-app-panel px-3.5 py-2.5 shadow-raised-sm"><div class="flex flex-wrap items-center gap-3"><div class="min-w-0 flex-1"><p class="truncate font-mono text-[13px] text-app-text">{{ executable.name }}</p><p class="text-xs text-app-text-muted">{{ executable.is_installed ? (executable.is_running ? 'Installed, running' : 'Installed') : 'Not installed' }}</p></div><MinutePicker v-model="timerMinutes[executable.name]" :disabled="gameActions?.isExecutableRunning(executable)" /><button type="button" class="neu-motion h-11 rounded-[14px] bg-app-panel px-[18px] text-[13px] font-semibold shadow-raised-sm hover:shadow-raised active:shadow-inset" :class="executable.is_running ? 'text-app-danger' : 'neu-convex text-app-accent hover:text-app-accent-hover'" @click="handleLaunch(executable)">{{ executable.is_running ? 'Stop' : executable.is_installed ? 'Play' : 'Install & Play' }}</button></div><div v-if="executable.is_running && executable.timer_minutes != null" class="mt-3 flex flex-wrap items-center gap-3"><span class="font-mono text-xs" :class="executable.timer_paused ? 'text-app-text-muted' : 'text-app-accent'">{{ executable.timer_paused ? 'Paused' : 'Ends in' }} {{ formatRemaining(executable.timer_remaining_seconds) }}</span><span class="h-2.5 w-24 overflow-hidden rounded-[5px] bg-app-panel shadow-inset" aria-hidden="true"><span class="block h-full rounded-[5px] bg-app-accent" :style="{ width: `${timerProgress(executable)}%` }" /></span><button type="button" class="neu-motion h-11 rounded-[14px] bg-app-panel px-3 text-[13px] text-app-text-muted shadow-raised-sm hover:shadow-raised hover:text-app-text active:shadow-inset" @click="handleTimerToggle(executable)">{{ executable.timer_paused ? 'Resume' : 'Pause' }}</button><button type="button" class="neu-motion h-11 rounded-[14px] bg-app-panel px-3 text-[13px] text-app-danger shadow-raised-sm hover:shadow-raised active:shadow-inset" @click="handleCancelTimer(executable)">Cancel timer</button></div></article></div></section>
</template>
